const items = $input.all();
const normalized = [];
for (const item of items) {
  const update = item.json || {};
  const message = update.message || update.edited_message || update.channel_post || {};
  const chat = message.chat || {};
  const from = message.from || {};
  const document = message.document || null;
  const rawText = typeof message.text === 'string' ? message.text : '';
  const trimmedText = rawText.trim();
  const messageDate = typeof message.date === 'number' ? new Date(message.date * 1000) : new Date();
  const attachmentKeys = ['photo', 'audio', 'video', 'voice', 'video_note', 'animation', 'sticker', 'location', 'venue', 'contact', 'poll', 'dice'];
  let hasOtherAttachment = false;
  for (const key of attachmentKeys) {
    if (message[key]) {
      hasOtherAttachment = true;
    }
  }
  normalized.push({
    json: {
      update_id: update.update_id !== undefined ? update.update_id : null,
      chat_id: chat.id !== undefined ? chat.id : null,
      chat_type: chat.type || '',
      chat_title: chat.title || '',
      user_id: from.id !== undefined ? from.id : null,
      username: from.username || '',
      first_name: from.first_name || '',
      message_id: message.message_id !== undefined ? message.message_id : null,
      timestamp: messageDate.toISOString(),
      message_text: rawText,
      document_file_id: document && document.file_id ? document.file_id : '',
      document_file_name: document && document.file_name ? document.file_name : '',
      document_mime_type: document && document.mime_type ? document.mime_type : '',
      has_text: trimmedText.length > 0,
      has_document: Boolean(document),
      has_other_attachment: hasOtherAttachment,
      is_bot_command: /^[/][A-Za-z0-9_]+/.test(trimmedText)
    }
  });
}
return normalized;

const items = $input.all();
const detected = [];
for (const item of items) {
  const data = item.json || {};
  const fileName = data.document_file_name || '';
  const mimeType = data.document_mime_type || '';
  const extensionMatch = /[.]([A-Za-z0-9]+)$/.exec(fileName);
  const documentExtension = extensionMatch ? extensionMatch[1].toLowerCase() : '';
  let messageKind = 'empty';
  if (data.has_document === true) {
    messageKind = 'document';
  } else if (data.has_text === true) {
    messageKind = 'text';
  } else if (data.has_other_attachment === true) {
    messageKind = 'unsupported';
  }
  let documentKind = 'none';
  if (messageKind === 'document') {
    const looksLikeTxt = mimeType === 'text/plain' || documentExtension === 'txt';
    documentKind = looksLikeTxt ? 'txt' : 'other';
  }
  detected.push({
    json: Object.assign({}, data, {
      message_kind: messageKind,
      document_kind: documentKind,
      document_extension: documentExtension
    })
  });
}
return detected;

const MIN_TRANSCRIPT_LENGTH = 30;
const items = $input.all();
const validated = [];
for (const item of items) {
  const data = item.json || {};
  const rawText = typeof data.message_text === 'string' ? data.message_text : '';
  const text = rawText.trim();
  let status = 'invalid';
  let reason = '';
  let message = '';
  if (data.message_kind === 'document') {
    status = 'document';
    reason = 'document_received';
    message = 'Document received.';
  } else if (data.message_kind === 'empty') {
    status = 'empty';
    reason = 'empty_message';
    message = 'I received an empty message. Please send the meeting transcript as text.';
  } else if (data.message_kind === 'unsupported') {
    status = 'unsupported';
    reason = 'unsupported_message_type';
    message = 'I can only work with text transcripts. Please send the transcript as a text message or a .txt file.';
  } else if (data.is_bot_command === true) {
    status = 'invalid';
    reason = 'bot_command';
    message = 'That looks like a bot command. Please send the meeting transcript itself as a text message or a .txt file.';
  } else if (text.length === 0) {
    status = 'empty';
    reason = 'empty_message';
    message = 'I received an empty message. Please send the meeting transcript as text.';
  } else if (text.length < MIN_TRANSCRIPT_LENGTH) {
    status = 'invalid';
    reason = 'insufficient_content';
    message = 'That message is too short to be a meeting transcript. Please send the full transcript.';
  } else {
    status = 'ready';
    reason = 'ok';
    message = 'Transcript accepted.';
  }
  validated.push({
    json: Object.assign({}, data, {
      transcript_status: status,
      validation_reason: reason,
      validation_message: message,
      transcript_text: status === 'ready' ? text : '',
      transcript_char_count: text.length,
      transcript_word_count: text.split(/\s+/).filter(Boolean).length
    })
  });
}
return validated;

const items = $input.all();
const built = [];
for (const item of items) {
  const data = item.json || {};
  built.push({
    json: {
      chat_id: data.chat_id !== undefined ? data.chat_id : null,
      user_id: data.user_id !== undefined ? data.user_id : null,
      message_id: data.message_id !== undefined ? data.message_id : null,
      source_type: 'text',
      transcript: typeof data.transcript_text === 'string' ? data.transcript_text : '',
      meeting_timestamp: data.timestamp || ''
    }
  });
}
return built;

const meta = $('Transcript Validation').item.json;
const items = $input.all();
const built = [];
for (const item of items) {
  const data = item.json || {};
  built.push({
    json: {
      chat_id: meta.chat_id !== undefined ? meta.chat_id : null,
      user_id: meta.user_id !== undefined ? meta.user_id : null,
      message_id: meta.message_id !== undefined ? meta.message_id : null,
      source_type: 'txt',
      transcript: typeof data.transcript === 'string' ? data.transcript.trim() : '',
      meeting_timestamp: meta.timestamp || ''
    }
  });
}
return built;

const TZ = 'Asia/Kolkata';
const IST_OFFSET_MIN = 330;
const MONTHS = { january:0, jan:0, february:1, feb:1, march:2, mar:2, april:3, apr:3, may:4, june:5, jun:5, july:6, jul:6, august:7, aug:7, september:8, sep:8, sept:8, october:9, oct:9, november:10, nov:10, december:11, dec:11 };
const WEEKDAYS = { sunday:0, sun:0, monday:1, mon:1, tuesday:2, tue:2, tues:2, wednesday:3, wed:3, thursday:4, thu:4, thur:4, thurs:4, friday:5, fri:5, saturday:6, sat:6 };
const VAGUE_RE = /\b(soon|asap|later|shortly|eventually|sometime|some time|tbd|tba|to be decided|to be announced|when possible|as and when|in a bit|in a while|at the earliest)\b/i;
const STATUS_SET = ['Not Started', 'In Progress', 'Blocked', 'Completed', 'Not specified'];
const CONFIDENCE_SET = ['High', 'Medium', 'Low'];
const ASSIGNMENT_SET = ['Explicit', 'Inferred', 'Unassigned'];
const DAY_MS = 86400000;

function pad2(n) { return n < 10 ? '0' + n : '' + n; }
function utcMs(y, m, d) { return Date.UTC(y, m, d); }
function isoOf(ms) {
  const t = new Date(ms);
  return t.getUTCFullYear() + '-' + pad2(t.getUTCMonth() + 1) + '-' + pad2(t.getUTCDate());
}
function lastDayOfMonth(y, m) { return new Date(Date.UTC(y, m + 1, 0)).getUTCDate(); }
function istParts(iso) {
  if (!iso) return null;
  const dt = new Date(iso);
  if (isNaN(dt.getTime())) return null;
  const s = new Date(dt.getTime() + IST_OFFSET_MIN * 60000);
  return { y: s.getUTCFullYear(), m: s.getUTCMonth(), d: s.getUTCDate(), dow: s.getUTCDay() };
}

function normalizeOwner(raw) {
  if (typeof raw !== 'string') return { owner: 'Unassigned', changed: true };
  const t = raw.trim();
  if (!t || /^(unassigned|unknown|none|n\/a|na|tbd|tba|-|not assigned|no owner)$/i.test(t)) {
    return { owner: 'Unassigned', changed: t.toLowerCase() !== 'unassigned' };
  }
  return { owner: t, changed: false };
}

function normalizeEnum(raw, allowed, fallback) {
  if (typeof raw === 'string') {
    const t = raw.trim();
    const hit = allowed.find(function (s) { return s.toLowerCase() === t.toLowerCase(); });
    if (hit) return { value: hit, changed: hit !== raw };
  }
  return { value: fallback, changed: true };
}

function parseDeadline(raw, meeting) {
  const original = typeof raw === 'string' ? raw.trim() : '';
  if (!original || /^(not specified|none|n\/a|na|unknown|-)$/i.test(original)) {
    return { deadline: 'Not specified', deadline_original: original || 'Not specified', deadline_resolved: null, deadline_status: 'missing', deadline_flags: [] };
  }
  if (!meeting) {
    return { deadline: original, deadline_original: original, deadline_resolved: null, deadline_status: 'unresolved', deadline_flags: ['meeting_timestamp_unavailable'] };
  }

  const base = utcMs(meeting.y, meeting.m, meeting.d);
  const flags = [];
  let ambiguous = false;
  let m;

  // 1. Absolute dates
  const abs = [];

  const reIso = /\b(\d{4})-(\d{2})-(\d{2})\b/g;
  while ((m = reIso.exec(original))) abs.push(utcMs(+m[1], +m[2] - 1, +m[3]));

  const reDMonth = /\b(\d{1,2})(?:st|nd|rd|th)?\s+(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\b(?:\s*,?\s*(\d{4}))?/gi;
  while ((m = reDMonth.exec(original))) {
    const mon = MONTHS[m[2].toLowerCase()];
    const day = +m[1];
    if (mon === undefined || day < 1 || day > 31) continue;
    let cand;
    if (m[3]) {
      cand = utcMs(+m[3], mon, day);
    } else {
      cand = utcMs(meeting.y, mon, day);
      if (cand < base) {
        cand = utcMs(meeting.y + 1, mon, day);
        if (cand - base > 180 * DAY_MS) ambiguous = true;
      }
    }
    abs.push(cand);
  }

  const reMonthD = /\b(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s+(\d{1,2})(?:st|nd|rd|th)?\b(?:\s*,?\s*(\d{4}))?/gi;
  while ((m = reMonthD.exec(original))) {
    const mon = MONTHS[m[1].toLowerCase()];
    const day = +m[2];
    if (mon === undefined || day < 1 || day > 31) continue;
    let cand;
    if (m[3]) {
      cand = utcMs(+m[3], mon, day);
    } else {
      cand = utcMs(meeting.y, mon, day);
      if (cand < base) {
        cand = utcMs(meeting.y + 1, mon, day);
        if (cand - base > 180 * DAY_MS) ambiguous = true;
      }
    }
    abs.push(cand);
  }

  const reNum = /\b(\d{1,2})[\/.](\d{1,2})(?:[\/.](\d{2,4}))?\b/g;
  while ((m = reNum.exec(original))) {
    const day = +m[1];
    const mon = +m[2];
    if (mon < 1 || mon > 12 || day < 1 || day > 31) continue;
    let y = m[3] ? +m[3] : meeting.y;
    if (y < 100) y += 2000;
    let cand = utcMs(y, mon - 1, day);
    if (!m[3] && cand < base) cand = utcMs(y + 1, mon - 1, day);
    abs.push(cand);
    ambiguous = true;
  }

  const reDayList = /\b(\d{1,2})(?:st|nd|rd|th)?\s*(?:or|and|to|-)\s*(\d{1,2})(?:st|nd|rd|th)?\s+(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\b/gi;
  while ((m = reDayList.exec(original))) {
    const mon = MONTHS[m[3].toLowerCase()];
    if (mon === undefined) continue;
    [+m[1], +m[2]].forEach(function (day) {
      if (day < 1 || day > 31) return;
      let cand = utcMs(meeting.y, mon, day);
      if (cand < base) cand = utcMs(meeting.y + 1, mon, day);
      abs.push(cand);
    });
  }

  const reMonthDayList = /\b(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s+(\d{1,2})(?:st|nd|rd|th)?\s*(?:or|and|to|-)\s*(\d{1,2})(?:st|nd|rd|th)?\b/gi;
  while ((m = reMonthDayList.exec(original))) {
    const mon = MONTHS[m[1].toLowerCase()];
    if (mon === undefined) continue;
    [+m[2], +m[3]].forEach(function (day) {
      if (day < 1 || day > 31) return;
      let cand = utcMs(meeting.y, mon, day);
      if (cand < base) cand = utcMs(meeting.y + 1, mon, day);
      abs.push(cand);
    });
  }

  if (abs.length > 0) {
    const unique = Array.from(new Set(abs));
    const resolved = Math.min.apply(null, unique);
    if (unique.length > 1) {
      flags.push('conflicting_deadline');
      flags.push('multiple_deadline_dates');
      if (ambiguous) flags.push('ambiguous_deadline');
      return { deadline: original, deadline_original: original, deadline_resolved: isoOf(resolved), deadline_status: 'conflicting', deadline_flags: flags };
    }
    if (ambiguous) flags.push('ambiguous_deadline');
    if (resolved < base) flags.push('deadline_before_meeting');
    return {
      deadline: original,
      deadline_original: original,
      deadline_resolved: isoOf(resolved),
      deadline_status: resolved < base ? 'conflicting' : (ambiguous ? 'ambiguous' : 'resolved'),
      deadline_flags: flags
    };
  }

  // 2. Weekday
  const reWd = /\b(?:(next|this|coming|upcoming)\s+)?(sunday|sun|monday|mon|tuesday|tues|tue|wednesday|wed|thursday|thurs|thur|thu|friday|fri|saturday|sat)\b/gi;
  m = reWd.exec(original);
  if (m) {
    const target = WEEKDAYS[m[2].toLowerCase()];
    let delta = (target - meeting.dow + 7) % 7;
    if (m[1] && /next/i.test(m[1])) {
      if (delta === 0) delta = 7;
      flags.push('ambiguous_deadline');
      ambiguous = true;
    }
    const resolved = base + delta * DAY_MS;
    return {
      deadline: original,
      deadline_original: original,
      deadline_resolved: isoOf(resolved),
      deadline_status: ambiguous ? 'ambiguous' : 'resolved',
      deadline_flags: flags
    };
  }

  // 3. Relative expressions
  const lower = original.toLowerCase();
  let rel = null;
  let vague = false;

  if (/\btoday\b/.test(lower)) {
    rel = base;
  } else if (/\bday after tomorrow\b/.test(lower)) {
    rel = base + 2 * DAY_MS;
  } else if (/\btomorrow\b/.test(lower)) {
    rel = base + DAY_MS;
  } else if ((m = /\bin\s+(\d{1,2})\s*(day|days|week|weeks)\b/.exec(lower))) {
    const unit = m[2].indexOf('week') === 0 ? 7 : 1;
    rel = base + (+m[1]) * unit * DAY_MS;
  } else if (/\bnext week\b/.test(lower)) {
    rel = base + 7 * DAY_MS;
    vague = true;
  } else if (/\bend of (the )?week\b|\beow\b/.test(lower)) {
    const delta = (0 - meeting.dow + 7) % 7;
    rel = base + delta * DAY_MS;
    vague = true;
  } else if (/\bnext month\b/.test(lower)) {
    const nm = new Date(Date.UTC(meeting.y, meeting.m + 1, 1));
    rel = utcMs(nm.getUTCFullYear(), nm.getUTCMonth(), Math.min(meeting.d, lastDayOfMonth(nm.getUTCFullYear(), nm.getUTCMonth())));
    vague = true;
  } else if (/\bend of (the )?month\b/.test(lower)) {
    rel = utcMs(meeting.y, meeting.m, lastDayOfMonth(meeting.y, meeting.m));
    vague = true;
  }

  if (rel !== null) {
    if (vague) flags.push('vague_deadline');
    if (rel < base) flags.push('deadline_before_meeting');
    return {
      deadline: original,
      deadline_original: original,
      deadline_resolved: isoOf(rel),
      deadline_status: vague ? 'vague' : 'resolved',
      deadline_flags: flags
    };
  }

  // 4. Unresolvable
  if (VAGUE_RE.test(original)) {
    flags.push('vague_deadline');
    return { deadline: original, deadline_original: original, deadline_resolved: null, deadline_status: 'vague', deadline_flags: flags };
  }
  flags.push('unresolved_deadline');
  return { deadline: original, deadline_original: original, deadline_resolved: null, deadline_status: 'unresolved', deadline_flags: flags };
}

// ---------- read the AI output ----------
const item = $json || {};
let candidate = Object.prototype.hasOwnProperty.call(item, 'output') ? item.output : item;
let rawPreview = '';
let parsedFromString = false;
let parseFailed = false;

if (typeof candidate === 'string') {
  rawPreview = candidate.slice(0, 1200);
  const cleaned = candidate.replace(/^[\s]*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60[\s]*$/, '').trim();
  try {
    candidate = JSON.parse(cleaned);
    parsedFromString = true;
  } catch (e) {
    candidate = undefined;
    parseFailed = true;
  }
} else {
  try { rawPreview = JSON.stringify(candidate).slice(0, 1200); } catch (e) { rawPreview = ''; }
}

const errors = [];
const warnings = [];

// ---------- source metadata ----------
let source = {};
try { source = $('Transcript Ready for AI').first().json || {}; } catch (e) { source = {}; }
const meetingTimestamp = source.meeting_timestamp || null;
const meeting = istParts(meetingTimestamp);

// ---------- structural validation ----------
if (candidate === undefined || candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) {
  errors.push({
    code: parseFailed ? 'invalid_json' : 'output_not_object',
    field: 'output',
    message: parseFailed ? 'The AI output is not valid JSON.' : 'The AI output is not a JSON object.'
  });
}

if (errors.length === 0) {
  if (typeof candidate.summary !== 'string' || candidate.summary.trim() === '') {
    errors.push({ code: 'missing_summary', field: 'summary', message: 'The AI output has no usable summary.' });
  }
  if (!Array.isArray(candidate.decisions)) {
    errors.push({ code: 'decisions_not_array', field: 'decisions', message: 'decisions is not an array.' });
  }
  if (!Array.isArray(candidate.action_items)) {
    errors.push({ code: 'action_items_not_array', field: 'action_items', message: 'action_items is not an array.' });
  }
  if (!Array.isArray(candidate.open_questions)) {
    errors.push({ code: 'open_questions_not_array', field: 'open_questions', message: 'open_questions is not an array.' });
  }
}

// ---------- decisions ----------
const decisions = [];
if (errors.length === 0) {
  candidate.decisions.forEach(function (d, i) {
    if (!d || typeof d !== 'object' || Array.isArray(d)) {
      errors.push({ code: 'malformed_decision', field: 'decisions[' + i + ']', message: 'Decision ' + (i + 1) + ' is not an object.' });
      return;
    }
    if (typeof d.decision !== 'string' || d.decision.trim() === '') {
      errors.push({ code: 'malformed_decision', field: 'decisions[' + i + '].decision', message: 'Decision ' + (i + 1) + ' has no decision text.' });
      return;
    }
    if (typeof d.evidence !== 'string' || d.evidence.trim() === '') {
      warnings.push({ code: 'missing_evidence', field: 'decisions[' + i + '].evidence', message: 'Decision ' + (i + 1) + ' has no supporting evidence.' });
    }
    decisions.push({ decision: d.decision.trim(), evidence: typeof d.evidence === 'string' ? d.evidence.trim() : '' });
  });
}

// ---------- action items ----------
const actionItems = [];
if (errors.length === 0) {
  candidate.action_items.forEach(function (a, i) {
    if (!a || typeof a !== 'object' || Array.isArray(a)) {
      errors.push({ code: 'malformed_action_item', field: 'action_items[' + i + ']', message: 'Action item ' + (i + 1) + ' is not an object.' });
      return;
    }
    if (typeof a.task !== 'string' || a.task.trim() === '') {
      errors.push({ code: 'malformed_action_item', field: 'action_items[' + i + '].task', message: 'Action item ' + (i + 1) + ' has no task description.' });
      return;
    }

    const flags = [];
    const ownerNorm = normalizeOwner(a.owner);
    if (ownerNorm.changed) {
      warnings.push({ code: 'owner_normalized', field: 'action_items[' + i + '].owner', message: 'Action item ' + (i + 1) + ' had a missing or unusable owner; normalized to Unassigned.', action_index: i });
    }
    const deadlineNorm = parseDeadline(a.deadline, meeting);
    if (deadlineNorm.deadline_status === 'missing' && a.deadline !== 'Not specified') {
      warnings.push({ code: 'deadline_normalized', field: 'action_items[' + i + '].deadline', message: 'Action item ' + (i + 1) + ' had a missing deadline; normalized to Not specified.', action_index: i });
    }
    deadlineNorm.deadline_flags.forEach(function (f) { if (flags.indexOf(f) === -1) flags.push(f); });
    if (deadlineNorm.deadline_flags.length > 0) {
      warnings.push({ code: 'deadline_flagged', field: 'action_items[' + i + '].deadline', message: 'Action item ' + (i + 1) + ' deadline "' + deadlineNorm.deadline + '" was flagged: ' + deadlineNorm.deadline_flags.join(', ') + '.', action_index: i });
    }

    const statusNorm = normalizeEnum(a.status, STATUS_SET, 'Not specified');
    if (statusNorm.changed) {
      warnings.push({ code: 'status_normalized', field: 'action_items[' + i + '].status', message: 'Action item ' + (i + 1) + ' had an invalid status; normalized to ' + statusNorm.value + '.', action_index: i });
    }
    const confNorm = normalizeEnum(a.confidence, CONFIDENCE_SET, 'Low');
    if (confNorm.changed) {
      warnings.push({ code: 'confidence_normalized', field: 'action_items[' + i + '].confidence', message: 'Action item ' + (i + 1) + ' had an invalid confidence; normalized to ' + confNorm.value + '.', action_index: i });
    }
    let assignment = normalizeEnum(a.assignment_type, ASSIGNMENT_SET, ownerNorm.owner === 'Unassigned' ? 'Unassigned' : 'Inferred');
    if (assignment.changed) {
      warnings.push({ code: 'assignment_type_normalized', field: 'action_items[' + i + '].assignment_type', message: 'Action item ' + (i + 1) + ' had an invalid assignment_type; normalized to ' + assignment.value + '.', action_index: i });
    }

    if (ownerNorm.owner === 'Unassigned' && assignment.value !== 'Unassigned') {
      assignment = { value: 'Unassigned', changed: true };
      warnings.push({ code: 'assignment_type_corrected', field: 'action_items[' + i + '].assignment_type', message: 'Action item ' + (i + 1) + ' had no owner; assignment_type corrected to Unassigned.', action_index: i });
    }
    if (ownerNorm.owner !== 'Unassigned' && assignment.value === 'Unassigned') {
      assignment = { value: 'Inferred', changed: true };
      warnings.push({ code: 'assignment_type_corrected', field: 'action_items[' + i + '].assignment_type', message: 'Action item ' + (i + 1) + ' has an owner but was marked Unassigned; corrected to Inferred.', action_index: i });
    }

    let confidence = confNorm.value;
    if (ownerNorm.owner === 'Unassigned') confidence = 'Low';

    const ownershipUncertain = ownerNorm.owner === 'Unassigned' || assignment.value === 'Unassigned' || assignment.value === 'Inferred' || confidence === 'Low';
    if (ownershipUncertain) {
      if (flags.indexOf('ownership_uncertain') === -1) flags.push('ownership_uncertain');
      if (ownerNorm.owner === 'Unassigned' && flags.indexOf('unassigned_owner') === -1) flags.push('unassigned_owner');
      warnings.push({ code: 'uncertain_ownership', field: 'action_items[' + i + '].owner', message: 'Action item ' + (i + 1) + ' has uncertain ownership (' + assignment.value + ', confidence ' + confidence + ').', action_index: i });
    }

    if (typeof a.evidence !== 'string' || a.evidence.trim() === '') {
