const MAX_CHARS = 3800;

function chunkText(text, max) {
  const lines = String(text).split('\n');
  const chunks = [];
  let buf = [];
  let len = 0;
  function flush() {
    if (buf.length > 0) {
      chunks.push(buf.join('\n'));
      buf = [];
      len = 0;
    }
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.length > max) {
      flush();
      for (let j = 0; j < line.length; j += max) chunks.push(line.slice(j, j + max));
      continue;
    }
    const add = buf.length === 0 ? line.length : len + 1 + line.length;
    if (add > max) {
      flush();
      buf = [line];
      len = line.length;
    } else {
      buf.push(line);
      len = add;
    }
  }
  flush();
  if (chunks.length === 0) chunks.push('');
  return chunks;
}

