const total = chunks.length;

return chunks.map(function (chunk, i) {
  const text = total > 1 ? chunk + '\n\n\u2014 part ' + (i + 1) + '/' + total : chunk;
  return {
    json: {
      status: 'ok',
      chat_id: chatId,
      message_id: messageId,
      meeting_id: meetingId,
      part: i + 1,
      total_parts: total,
      telegram_message: text
    }
  };
});

// Phase 6 - turn an Excel write/conversion error into a helpful Telegram failure message.

const d = $json || {};

let validated = {};
try { validated = $('Validate AI Output').first().json || {}; } catch (e) { validated = {}; }
let prepared = {};
try { prepared = $('Prepare Storage Records').first().json || {}; } catch (e) { prepared = {}; }

const raw = d.error;
const message = typeof raw === 'string'
  ? raw
  : (raw && raw.message ? String(raw.message) : 'Unknown storage error');

let execId = 'n/a';
try { if ($execution && $execution.id) execId = String($execution.id); } catch (e) { execId = 'n/a'; }

const text = [
  '\u26a0\ufe0f Your meeting was processed, but saving the Excel files failed.',
  '',
  'Error: ' + message,
  '',
  'Some or all rows may not have been saved, and no summary was sent.',
  'Reference: ' + execId
].join('\n');

return [{
  json: {
    status: 'storage_error',
    chat_id: validated.chat_id !== undefined ? validated.chat_id : null,
    message_id: validated.message_id !== undefined ? validated.message_id : null,
    meeting_id: prepared.meeting_id || '',
    telegram_message: text,
    error: message
  }
}];
